package com.example.starter.coldchain.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 建货件请求。
 *
 * @param shipmentId                货件唯一标识
 * @param minTemp                   允许温度闭区间下限（摄氏度，含端点）
 * @param maxTemp                   允许温度闭区间上限（摄氏度，含端点）
 * @param maxExcursionMinutes       允许的最大连续超限分钟数
 * @param maxSampleIntervalSeconds  相邻读数最大采样间隔（秒）
 * @param custodian                 首段保管方
 * @param startTime                 首段开始时间（Asia/Shanghai）
 */
public record CreateShipmentRequest(
        @NotBlank String shipmentId,
        @NotNull Double minTemp,
        @NotNull Double maxTemp,
        @Min(0) int maxExcursionMinutes,
        @Min(1) int maxSampleIntervalSeconds,
        @NotBlank String custodian,
        java.time.LocalDateTime startTime
) {
}

package com.example.starter.coldchain.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.LocalDateTime;

/**
 * 写温度读数请求。
 *
 * @param sequenceNo   设备采样序号，货件内全局严格递增
 * @param deviceNo     设备序号（设备标识）
 * @param sampledAt    采样时间（Asia/Shanghai）
 * @param temperature  采样温度（摄氏度，须为有限数值）
 */
public record ReadingRequest(
        @NotNull Long sequenceNo,
        @NotBlank String deviceNo,
        @NotNull LocalDateTime sampledAt,
        @NotNull Double temperature
) {
}

package com.example.starter.coldchain.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.LocalDateTime;

/**
 * 交接请求：在一个事务内关闭旧段、判定结果并打开新段。
 *
 * @param requestId       幂等键
 * @param expectedVersion 期望关闭的当前开放段版本号
 * @param receiver        接收保管方（新段保管方）
 * @param handoverAt      交接时间（Asia/Shanghai）
 * @param lastSequence    本段末个设备序号
 */
public record HandoverRequest(
        @NotBlank String requestId,
        @NotNull Integer expectedVersion,
        @NotBlank String receiver,
        @NotNull LocalDateTime handoverAt,
        @NotNull Long lastSequence
) {
}

package com.example.starter.coldchain.dto;

import com.example.starter.coldchain.domain.SegmentStatus;
import com.example.starter.coldchain.entity.TransportSegment;

import java.time.LocalDateTime;

/**
 * 交接结果（同 requestId 同参重放返回首次冻结的结果）。
 *
 * @param requestId      幂等键
 * @param shipmentId     货件标识
 * @param closedVersion  被关闭的旧段版本号
 * @param status         旧段判定结果：CLEAR/EXCURSION/INCOMPLETE
 * @param newVersion     新打开段的版本号
 * @param receiver       新段保管方
 * @param startTime      新段开始时间（即交接时间）
 * @param replayed       是否为幂等重放
 */
public record HandoverResponse(
        String requestId,
        String shipmentId,
        int closedVersion,
        SegmentStatus status,
        int newVersion,
        String receiver,
        LocalDateTime startTime,
        boolean replayed
) {

    /**
     * 依据交接记录与新段信息构造响应。
     */
    public static HandoverResponse of(TransportSegment closed, TransportSegment opened,
                                      String requestId, boolean replayed) {
        return new HandoverResponse(
                requestId,
                closed.shipmentId(),
                closed.version(),
                closed.status(),
                opened.version(),
                opened.custodian(),
                opened.startTime(),
                replayed
        );
    }
}

package com.example.starter.coldchain.dto;

import com.example.starter.coldchain.entity.TemperatureReading;

import java.time.LocalDateTime;

/**
 * 读数写入结果。
 *
 * @param sequenceNo   序号
 * @param deviceNo     设备序号
 * @param sampledAt    采样时间
 * @param temperature  采样温度
 * @param replayed     是否为同序号同参重放
 */
public record ReadingResponse(
        long sequenceNo,
        String deviceNo,
        LocalDateTime sampledAt,
        double temperature,
        boolean replayed
) {

    public static ReadingResponse of(TemperatureReading reading, boolean replayed) {
        return new ReadingResponse(
                reading.sequenceNo(),
                reading.deviceNo(),
                reading.sampledAt(),
                reading.temperature(),
                replayed
        );
    }
}

package com.example.starter.coldchain.dto;

import com.example.starter.coldchain.domain.SegmentStatus;
import com.example.starter.coldchain.entity.TemperatureReading;

import java.time.LocalDateTime;
import java.util.List;

/**
 * 分段证据查询结果：段元数据 + 段内读数（按序号升序）。
 *
 * @param version        段版本号
 * @param custodian      保管方
 * @param startTime      段开始时间
 * @param endTime        段关闭时间；开放段为 {@code null}
 * @param firstSequence  首序号（含）
 * @param lastSequence   末序号（含）；开放段为 {@code null}
 * @param status         段状态
 * @param readings       段内读数证据（按序号升序）
 */
public record SegmentEvidenceResponse(
        int version,
        String custodian,
        LocalDateTime startTime,
        LocalDateTime endTime,
        long firstSequence,
        Long lastSequence,
        SegmentStatus status,
        List<ReadingView> readings
) {

    /**
     * 证据中的单条读数视图。
     */
    public record ReadingView(
            long sequenceNo,
            String deviceNo,
            LocalDateTime sampledAt,
            double temperature
    ) {

        public static ReadingView from(TemperatureReading r) {
            return new ReadingView(r.sequenceNo(), r.deviceNo(), r.sampledAt(), r.temperature());
        }
    }
}

