/**
 * 分段温度判定（纯逻辑，便于单元测试）：
 * 缺号、相邻采样间隔超限为 {@link SegmentStatus#INCOMPLETE}；
 * 连续超限时长（相邻读数之间沿用前一读数）超过允许分钟数为 {@link SegmentStatus#EXCURSION}；
 * 否则为 {@link SegmentStatus#CLEAR}。端点等于阈值视为合格。
 */
public final class SegmentEvaluator {

    private SegmentEvaluator() {
    }

    /**
     * 判定段结果。
     *
     * @param shipment    货件阈值配置
     * @param readings    段内读数（调用方保证按序号升序、连续无重复）
     * @param expectedLastSequence 交接声明的末序号（用于缺号检查）
     */
    public static SegmentStatus evaluate(Shipment shipment, List<TemperatureReading> readings,
                                         long expectedLastSequence) {
        throw new UnsupportedOperationException();
    }
}

