22	import org.springframework.stereotype.Service;
23	import org.springframework.transaction.annotation.Transactional;
24	
25	import java.time.Clock;
26	import java.time.LocalDateTime;
27	import java.util.List;
28	
29	/**
30	 * 冷链运输交接与温度偏离判定服务实现。
31	 *
32	 * <p>写读数与交接均在事务内先对货件行加 {@code FOR UPDATE} 行锁，
33	 * 从而形成按货件串行化的一致提交顺序；唯一约束兜底序号与 requestId 幂等。
34	 */
35	@Service
36	public class ColdChainServiceImpl implements ColdChainService {
37	
38	    /** 首段默认起始设备序号。 */
39	    private static final long FIRST_SEGMENT_FIRST_SEQUENCE = 1L;
40	
41	    private final ColdChainRepository repository;
42	    private final Clock clock;
43	
44	    public ColdChainServiceImpl(ColdChainRepository repository, Clock clock) {
45	        this.repository = repository;
46	        this.clock = clock;
47	    }
48	
49	    @Override
50	    @Transactional
51	    public Shipment createShipment(CreateShipmentRequest request) {
52	        if (!Double.isFinite(request.minTemp()) || !Double.isFinite(request.maxTemp())
53	                || request.minTemp() > request.maxTemp()) {
54	            throw new ValidationException("温度闭区间不合法：需为有限数值且下限不大于上限");
55	        }
56	        LocalDateTime startTime = request.startTime() != null
57	                ? request.startTime() : LocalDateTime.now(clock);
58	        if (repository.findShipment(request.shipmentId()) != null) {
59	            throw new ConflictException("货件已存在: " + request.shipmentId());
60	        }
61	        LocalDateTime now = LocalDateTime.now(clock);
62	        Shipment shipment = new Shipment(
63	                request.shipmentId(),
64	                request.minTemp(),
65	                request.maxTemp(),
66	                request.maxExcursionMinutes(),
67	                request.maxSampleIntervalSeconds(),
68	                1,
69	                now);
70	        TransportSegment firstSegment = new TransportSegment(
71	                null,
72	                request.shipmentId(),
73	                1,
74	                request.custodian(),
75	                startTime,
76	                null,
77	                FIRST_SEGMENT_FIRST_SEQUENCE,
78	                null,
79	                SegmentStatus.OPEN);
80	        try {
81	            repository.insertShipment(shipment);
82	            repository.insertSegment(firstSegment);
83	        } catch (DuplicateKeyException e) {
84	            throw new ConflictException("货件已存在: " + request.shipmentId());
85	        }
86	        return shipment;
87	    }
88	
89	    @Override
90	    public Shipment getShipment(String shipmentId) {
91	        Shipment shipment = repository.findShipment(shipmentId);
92	        if (shipment == null) {
93	            throw new NotFoundException("货件不存在: " + shipmentId);
94	        }
95	        return shipment;
96	    }
97	
98	    @Override
99	    @Transactional
100	    public ReadingResponse writeReading(String shipmentId, ReadingRequest request) {
101	        if (!Double.isFinite(request.temperature())) {
102	            throw new ValidationException("温度须为有限数值");
103	        }
104	        // 货件行锁：与交接事务互斥，保证写入与交接的提交顺序一致。
105	        Shipment shipment = repository.lockShipment(shipmentId);
106	        if (shipment == null) {
107	            throw new NotFoundException("货件不存在: " + shipmentId);
108	        }
109	
110	        TemperatureReading existing = repository.findReading(shipmentId, request.sequenceNo());
111	        if (existing != null) {
112	            if (sameParams(existing, request)) {
113	                // 同序号同参重放：返回原结果。
114	                return ReadingResponse.of(existing, true);
115	            }
116	            throw new ConflictException("同序号读数已存在且参数不同（deviceNo/sampledAt/temperature 改值冲突）");
117	        }
118	
119	        // 已关闭段拒绝补写其序号范围。
120	        if (belongsToClosedSegment(shipmentId, request.sequenceNo())) {
121	            throw new ValidationException("该序号属于已关闭运输段，禁止补写");
122	        }
123	
124	        // 时间单调性（允许乱序到达，但采样时间须随序号严格递增）。
125	        TemperatureReading prev = repository.findReadingBefore(shipmentId, request.sequenceNo());
126	        if (prev != null && !request.sampledAt().isAfter(prev.sampledAt())) {
127	            throw new ValidationException("采样时间相对前一序号倒退或相等");
128	        }
129	        TemperatureReading next = repository.findReadingAfter(shipmentId, request.sequenceNo());
130	        if (next != null && !request.sampledAt().isBefore(next.sampledAt())) {
131	            throw new ValidationException("采样时间相对后一序号倒退或相等");
132	        }
133	
134	        TemperatureReading reading = new TemperatureReading(
135	                null,
136	                shipmentId,
137	                request.sequenceNo(),
138	                request.deviceNo(),
139	                request.sampledAt(),
140	                request.temperature());
141	        try {
142	            repository.insertReading(reading);
143	        } catch (DuplicateKeyException e) {
144	            // 并发下被其它事务抢先写入同序号。
145	            TemperatureReading winner = repository.findReading(shipmentId, request.sequenceNo());
146	            if (winner != null && sameParams(winner, request)) {
147	                return ReadingResponse.of(winner, true);
148	            }
149	            throw new ConflictException("同序号读数已存在且参数不同（deviceNo/sampledAt/temperature 改值冲突）");
150	        }
151	        return ReadingResponse.of(reading, false);
152	    }
153	
154	    @Override
155	    @Transactional
156	    public HandoverResponse handover(String shipmentId, HandoverRequest request) {
157	        // 快速幂等路径：已冻结的 requestId 直接返回首次结果（无需再加锁）。
158	        HandoverRecord frozen = repository.findHandover(request.requestId());
159	        if (frozen != null) {
160	            return replay(shipmentId, request, frozen);
161	        }
162	
163	        // 货件行锁：串行化同货件的交接与读数写入。
164	        Shipment shipment = repository.lockShipment(shipmentId);
165	        if (shipment == null) {
166	            throw new NotFoundException("货件不存在: " + shipmentId);
167	        }
168	        // 双重检查：可能在拿锁前已有同 requestId 事务提交。
169	        frozen = repository.findHandover(request.requestId());
170	        if (frozen != null) {
171	            return replay(shipmentId, request, frozen);
172	        }
173	
174	        // 拿锁后货件当前版本即权威版本；过期请求直接判版本冲突。
175	        if (shipment.currentVersion() != request.expectedVersion()) {
176	            throw new ConflictException("版本冲突：当前开放段版本为 " + shipment.currentVersion()
177	                    + "，请求期望版本为 " + request.expectedVersion());
178	        }
179	
180	        TransportSegment open = repository.lockOpenSegment(shipmentId);
181	        if (open == null) {
182	            throw new ConflictException("货件不存在开放运输段，无法交接");
183	        }
184	        if (open.version() != request.expectedVersion()) {
185	            throw new ConflictException("版本冲突：当前开放段版本为 " + open.version()
186	                    + "，请求期望版本为 " + request.expectedVersion());
187	        }
188	        if (request.receiver().equals(open.custodian())) {
189	            throw new ValidationException("保管方不匹配：接收方不得与当前保管方相同");
190	        }
191	        if (request.handoverAt().isBefore(open.startTime())) {
192	            throw new ValidationException("交接时间不得早于本段开始时间（时间倒退）");
193	        }
194	        if (request.lastSequence() < open.firstSequence() - 1) {
195	            throw new ValidationException("lastSequence 不得早于本段首序号");
196	        }
197	
198	        List<TemperatureReading> readings = repository.findReadingsBetween(
199	                shipmentId, open.firstSequence(), request.lastSequence());
200	        // 交接时间不得早于段内末条读数的采样时间（读数时间随序号单调，末条即最晚）。
201	        if (!readings.isEmpty()
202	                && request.handoverAt().isBefore(readings.get(readings.size() - 1).sampledAt())) {
203	            throw new ValidationException("交接时间早于段内末条读数采样时间（时间倒退）");
204	        }
205	        SegmentStatus status = SegmentEvaluator.evaluate(
206	                shipment, readings, open.firstSequence(), request.lastSequence());
207	
208	        String fingerprint = FingerprintUtil.sha256(shipmentId, request.expectedVersion(),
209	                request.receiver(), request.handoverAt(), request.lastSequence());
210	        LocalDateTime now = LocalDateTime.now(clock);
211	        HandoverRecord record = new HandoverRecord(
212	                request.requestId(),
213	                shipmentId,
214	                request.expectedVersion(),
215	                request.receiver(),
216	                request.handoverAt(),
217	                request.lastSequence(),
218	                fingerprint,
219	                null,
220	                null,
221	                now);
222	        try {
223	            // 先冻结请求键（与后续关闭/新开在同一事务，任何失败整体回滚）。
224	            repository.insertHandover(record);
225	        } catch (DuplicateKeyException e) {
226	            HandoverRecord winner = repository.findHandover(request.requestId());
227	            if (winner != null && winner.fingerprint().equals(fingerprint)) {
228	                return replay(shipmentId, request, winner);
229	            }
230	            throw new ConflictException("同 requestId 但请求参数不同（含 expectedVersion/lastSequence 变化）");
231	        }
232	
233	        int closed = repository.closeSegment(shipmentId, open.version(),
234	                request.handoverAt(), request.lastSequence(), status);
235	        if (closed == 0) {
236	            throw new ConflictException("版本冲突：运输段已被关闭");
237	        }
238	        int incremented = repository.compareAndIncrementVersion(shipmentId, open.version());
239	        if (incremented == 0) {
240	            throw new ConflictException("版本冲突：货件版本已变化");
241	        }
242	        int newVersion = open.version() + 1;
243	        TransportSegment newSegment = new TransportSegment(
244	                null,
245	                shipmentId,
246	                newVersion,
247	                request.receiver(),
248	                request.handoverAt(),
249	                null,
250	                request.lastSequence() + 1,
251	                null,
252	                SegmentStatus.OPEN);
253	        repository.insertSegment(newSegment);
254	        repository.completeHandover(request.requestId(), status, newVersion);
255	
256	        return new HandoverResponse(
257	                request.requestId(),
258	                shipmentId,
259	                open.version(),
260	                status,
261	                newVersion,
262	                request.receiver(),
263	                request.handoverAt(),
264	                false);
265	    }
266	
267	    @Override
268	    public List<SegmentEvidenceResponse> segmentEvidence(String shipmentId) {
269	        Shipment shipment = getShipment(shipmentId);
270	        List<TransportSegment> segments = repository.findAllSegments(shipmentId);
271	        Long maxSequence = repository.findMaxSequence(shipmentId);
272	        return segments.stream().map(segment -> {
273	            long upperBound;
274	            if (segment.lastSequence() != null) {
275	                upperBound = segment.lastSequence();
276	            } else if (maxSequence != null && maxSequence >= segment.firstSequence()) {
277	                upperBound = maxSequence;
278	            } else {
279	                upperBound = segment.firstSequence() - 1;
280	            }
281	            List<TemperatureReading> readings = upperBound < segment.firstSequence()
282	                    ? List.of()
283	                    : repository.findReadingsBetween(shipmentId, segment.firstSequence(), upperBound);
284	            List<SegmentEvidenceResponse.ReadingView> views = readings.stream()
285	                    .map(SegmentEvidenceResponse.ReadingView::from)
286	                    .toList();
287	            return new SegmentEvidenceResponse(
288	                    segment.version(),
289	                    segment.custodian(),
290	                    segment.startTime(),
291	                    segment.endTime(),
292	                    segment.firstSequence(),
293	                    segment.lastSequence(),
294	                    segment.status(),
295	                    views);
296	        }).toList();
297	    }
298	
299	    /** 同 requestId 重放：校验指纹后返回首次冻结的结果。 */
300	    private HandoverResponse replay(String shipmentId, HandoverRequest request, HandoverRecord frozen) {
301	        String fingerprint = FingerprintUtil.sha256(shipmentId, request.expectedVersion(),
302	                request.receiver(), request.handoverAt(), request.lastSequence());
303	        if (!frozen.shipmentId().equals(shipmentId) || !frozen.fingerprint().equals(fingerprint)) {
304	            throw new ConflictException("同 requestId 但请求参数不同（含 expectedVersion/lastSequence 变化）");
305	        }
306	        if (frozen.segmentStatus() == null || frozen.newVersion() == null) {
307	            throw new ConflictException("交接结果尚未冻结完成");
308	        }
309	        TransportSegment closedSegment = repository.findSegment(shipmentId, frozen.expectedVersion());
310	        TransportSegment openedSegment = repository.findSegment(shipmentId, frozen.newVersion());
311	        if (closedSegment == null || openedSegment == null) {
312	            throw new NotFoundException("交接关联运输段缺失");
313	        }
314	        return new HandoverResponse(
315	                frozen.requestId(),
316	                shipmentId,
317	                frozen.expectedVersion(),
318	                frozen.segmentStatus(),
319	                frozen.newVersion(),
320	                openedSegment.custodian(),
321	                openedSegment.startTime(),
322	                true);
323	    }
324	
325	    /** 判断序号是否落入任一已关闭段的首末序号闭区间。 */
326	    private boolean belongsToClosedSegment(String shipmentId, long sequenceNo) {
327	        return repository.findAllSegments(shipmentId).stream()
328	                .filter(s -> s.status() != SegmentStatus.OPEN)
329	                .anyMatch(s -> sequenceNo >= s.firstSequence()
330	                        && s.lastSequence() != null
331	                        && sequenceNo <= s.lastSequence());
332	    }
333	
334	    private boolean sameParams(TemperatureReading existing, ReadingRequest request) {
335	        return existing.deviceNo().equals(request.deviceNo())
336	                && existing.sampledAt().equals(request.sampledAt())
337	                && existing.temperature() == request.temperature();
338	    }
339	}
